#include <list>
#include <stdexcept>

class CustomThrowingType {
    // Type that might throw in constructor/copy
};

void safe_insert(std::list<CustomThrowingType>& l) {
    try {
        // If memory allocation fails during push_back,
        // the strong guarantee ensures 'l' remains unchanged.
        l.push_back(CustomThrowingType{}); 
    } catch (const std::bad_alloc& e) {
        // List state is still valid and unchanged.
        // No need for manual rollback.
    }
}
